DEEPENED_TASK_FRAME = {'bounded_prompt': 'The task does not estimate full coral mortality, fisheries loss, or ecological recovery.',
 'decisive_evidence_prompt': 'SST anomaly and persistence should decide the marine mechanism; land precipitation or '
                             'exposure is contextual.',
 'formula_prompt': 'Use thermal excess times duration, analogous to degree-heating accumulation where supported by '
                   'package fields.',
 'group': 'deepened_remaining_39',
 'mechanism_chain': ['sea-surface thermal anomaly',
                     'duration or persistence',
                     'land-context countercheck',
                     'marine-stress conclusion'],
 'mechanism_question': 'diagnose whether sustained sea-surface thermal stress dominates over land-weather or generic '
                       'coastal context',
 'new_title': 'Arabian Sea Sustained Marine Heat-Stress Diagnosis',
 'rejected_prompt': 'Reject land-weather or generic coastal-impact explanations if marine thermal stress is dominant.',
 'target_family': 'sustained_marine_heat_stress_diagnosis',
 'task_mode': 'deep_mechanism_diagnosis'}

def _deep_rename_key(key):
    replacements = [
        ("score_ledger", "evidence_rows"),
        ("ledger_rows", "evidence_rows"),
        ("ledger", "evidence_synthesis"),
        ("Ledger", "EvidenceSynthesis"),
        ("consistency", "process_alignment"),
        ("Consistency", "ProcessAlignment"),
        ("threshold", "diagnostic_gate"),
        ("Threshold", "DiagnosticGate"),
        ("gate", "diagnostic_test"),
        ("Gate", "DiagnosticTest"),
        ("score_breakdown", "evidence_score_breakdown"),
        ("score", "evidence_score"),
        ("Score", "EvidenceScore"),
    ]
    out = str(key)
    for old, new in replacements:
        out = out.replace(old, new)
    return out


def _deep_rename_obj(value, parent_key=None):
    protected_value_keys = {
        "answer",
        "final_label",
        "classification",
        "label",
        "diagnosis",
        "result",
        "answer_type",
        "task_family",
        "target_family",
    }
    if isinstance(value, dict):
        return {_deep_rename_key(k): _deep_rename_obj(v, k) for k, v in value.items()}
    if isinstance(value, list):
        return [_deep_rename_obj(v, parent_key) for v in value]
    if isinstance(value, str):
        if parent_key in protected_value_keys:
            return value
        out = value
        replacements = [
            ("ledger", "evidence synthesis"),
            ("Ledger", "Evidence synthesis"),
            ("consistency", "process alignment"),
            ("Consistency", "Process alignment"),
            ("threshold", "diagnostic gate"),
            ("Threshold", "Diagnostic gate"),
        ]
        for old, new in replacements:
            out = out.replace(old, new)
        return out
    return value

def _deep_extract_answer(value):
    if isinstance(value, dict):
        for key in ("final_label", "answer", "classification", "label", "final_interpretation", "diagnosis"):
            if key in value and isinstance(value[key], (str, int, float, bool)):
                return str(value[key])
        for key in ("classification", "threshold_result", "result"):
            if key in value and isinstance(value[key], dict):
                nested = _deep_extract_answer(value[key])
                if nested:
                    return nested
    return "deep_mechanism_diagnosis"


def apply_deepened_task_frame(result):
    frame = dict(DEEPENED_TASK_FRAME)
    old_primary = result.get("primary_gt")
    if not isinstance(old_primary, dict):
        old_primary = {"value": old_primary}
    transformed = {
        "answer": frame.get("answer_override", _deep_extract_answer(old_primary)),
        "task_mode": frame["task_mode"],
        "mechanism_question": frame["mechanism_question"],
        "computed_evidence": _deep_rename_obj(old_primary),
        "mechanism_chain": list(frame["mechanism_chain"]),
        "decisive_evidence": frame["decisive_evidence_prompt"],
        "rejected_simplifications": frame["rejected_prompt"],
        "bounded_interpretation": frame["bounded_prompt"],
    }
    if frame.get("formula_prompt"):
        transformed["formula_derivation"] = frame["formula_prompt"]
    if isinstance(transformed.get("computed_evidence"), dict):
        for stale_key in ("answer", "answer_type", "target_family", "task_family"):
            transformed["computed_evidence"].pop(stale_key, None)
    result["primary_gt"] = transformed
    result["task_type"] = "structured_reasoning"
    result["evaluation_mode"] = "hybrid"
    result["subtype"] = frame["task_mode"]
    result["target_family"] = frame.get("target_family", frame["task_mode"])
    result["deepened_reframe"] = {
        "group": frame["group"],
        "replaces_table_only_task": True,
        "new_title": frame["new_title"],
    }
    guidance = result.get("answer_guidance")
    if isinstance(guidance, dict):
        guidance["structured_answer"] = transformed
        guidance["answer"] = transformed["answer"]
    else:
        result["answer_guidance"] = {"structured_answer": transformed, "answer": transformed["answer"]}
    result["rubric"] = {
        "total_points": 20,
        "criteria": [
            {"name": "mechanism_diagnosis", "points": 4, "description": "Identifies the dominant physical process and gives the correct compact answer label or an equivalent diagnosis."},
            {"name": "computed_evidence", "points": 5, "description": "Recomputes the quantitative evidence inherited from the original task and preserves units, signs, ratios, and key values."},
            {"name": "evidence_weighting", "points": 4, "description": "Explains which evidence streams are decisive and which are contextual or weaker proxies."},
            {"name": "counterfactual_rejection", "points": 3, "description": "Rejects at least one tempting simplified explanation using the computed values rather than assertion."},
            {"name": "bounded_interpretation", "points": 2, "description": "States scale, timing, proxy, or uncertainty limits without adding unsupported losses or impacts."},
            {"name": "json_contract", "points": 2, "description": "Returns the requested structured mechanism-diagnosis JSON without reducing the answer to a row-only table or same-scale checklist."},
        ],
    }
    if frame.get("formula_prompt"):
        result["rubric"] = {
            "total_points": 20,
            "criteria": [
                {"name": "mechanism_diagnosis", "points": 3, "description": "Identifies the dominant physical process and gives the correct compact mechanism label or equivalent diagnosis."},
                {"name": "computed_evidence", "points": 4, "description": "Recomputes the package-derived quantitative evidence with correct units, signs, ratios, dates, and rounding."},
                {"name": "formula_derivation", "points": 3, "description": "Shows the requested physical formula, scaling relation, or timing relation and connects it to the computed values."},
                {"name": "evidence_weighting", "points": 3, "description": "Explains which evidence streams are decisive and which are contextual or weaker proxies."},
                {"name": "counterfactual_rejection", "points": 3, "description": "Rejects tempting simplified explanations using computed values rather than assertion."},
                {"name": "bounded_interpretation", "points": 2, "description": "States scale, timing, proxy, or uncertainty limits without adding unsupported losses or impacts."},
                {"name": "json_contract", "points": 2, "description": "Returns the requested structured mechanism-diagnosis JSON without reducing the answer to a row-only table."},
            ],
        }

    return result

def read_json(rel_path: str) -> dict[str, Any]:
    return json.loads((PACKAGE_DIR / rel_path).read_text(encoding="utf-8-sig"))


def read_text(rel_path: str) -> str:
    return (PACKAGE_DIR / rel_path).read_text(encoding="utf-8-sig", errors="replace")


def inclusive_days(start: str, end: str) -> int:
    return (date.fromisoformat(end) - date.fromisoformat(start)).days + 1


def round3(value: float) -> float:
    return round(float(value), 3)


def iter_pixels(image: Any) -> Iterable[Any]:
    if hasattr(image, "get_flattened_data"):
        return image.get_flattened_data()
    if hasattr(image, "getdata"):
        return image.getdata()
    raise TypeError("image object has no supported pixel stream")


def rgb_triplet(pixel: Any) -> tuple[float, float, float]:
    if isinstance(pixel, (tuple, list)):
        values = list(pixel)
    else:
        values = [pixel]
    if len(values) >= 3:
        return float(values[0]), float(values[1]), float(values[2])
    value = float(values[0])
    return value, value, value


def mean_luma(rel_path: str) -> float:
    image = Image.open(PACKAGE_DIR / rel_path).convert("RGB")
    total = 0.0
    count = 0
    for pixel in iter_pixels(image):
        red, green, blue = rgb_triplet(pixel)
        total += 0.2126 * red + 0.7152 * green + 0.0722 * blue
        count += 1
    if count == 0:
        raise ValueError(f"no pixels read from {rel_path}")
    return total / count


def exposure_file_share() -> float:
    with (PACKAGE_DIR / "metadata/files.csv").open("r", encoding="utf-8-sig", newline="") as handle:
        rows = list(csv.DictReader(handle))
    exposure_rows = [row for row in rows if row["data_category"] == "exposure_impact"]
    if not exposure_rows:
        raise ValueError("exposure_impact category is empty")
    population_rows = [
        row
        for row in exposure_rows
        if "worldpop" in " ".join([row["relative_path"], row["layer_name"], row["source_name"]]).lower()
    ]
    return len(population_rows) / len(exposure_rows)


def core_product_hits(page: str) -> dict[str, bool]:
    patterns = {
        "ssta": r"ct5km_ssta_v3\.1_indian_current\.png",
        "hotspot": r"ct5km_hs_v3\.1_indian_current\.png",
        "dhw": r"ct5km_dhw_v3\.1_indian_current\.png",
        "baa7": r"ct5km_baa5-max-7d_v3\.1_indian_current\.png",
    }
    return {name: bool(re.search(pattern, page)) for name, pattern in patterns.items()}


def build_ground_truth() -> dict[str, Any]:
    event = read_json("metadata/event.json")
    anchor = read_json(
        "data/event_reports/event_reports_003_Locked_event_anchor_2023_Indian_Ocean_Arabian_Sea_marine_heatwave_context.json"
    )
    crw_page = read_text("data/other/other_001_NOAA_Coral_Reef_Watch_5km_products.html")
    oisst_catalog = read_text(
        "data/event_catalogs/event_catalogs_002_NOAA_OISST_PSL_ERDDAP_sea-surface_temperature_THREDDS_catalog_XML.xml"
    )
    gpm = read_json("data/physical_hazard/physical_hazard_004_GPM_IMERG_V07_event_accumulated_precipitation.json")
    dnbr = read_json("data/physical_hazard/physical_hazard_006_Sentinel-2_SR_Harmonized_dNBR.json")
    population = read_json("data/exposure_impact/exposure_impact_002_WorldPop_GP_100m_population_sum.json")
    embedding = read_json("data/remote_sensing/remote_sensing_002_Google_Satellite_Embedding_annual_cosine-change_stats.json")

    dates = anchor["temporal_window"]
    duration_days = inclusive_days(dates["start_date"], dates["end_date"])
    land_sample_days = inclusive_days(gpm["start"], gpm["end"])
    land_sample_ratio = land_sample_days / duration_days
    gpm_peak_mean_ratio = gpm["stats"]["gpm_event_precip_mm_max"] / gpm["stats"]["gpm_event_precip_mm_mean"]
    dnbr_abs_mean = abs(dnbr["stats"]["sentinel2_dnbr_mean"])
    embedding_mean = embedding["stats"]["alphaearth_1_minus_cosine_mean"]
    pre_luma = mean_luma("data/remote_sensing/remote_sensing_003_pre.jpg")
    event_luma = mean_luma("data/remote_sensing/remote_sensing_004_event.jpg")
    visual_luma_delta_norm = abs(event_luma - pre_luma) / 255.0
    population_file_share = exposure_file_share()

    sst_anom_hits_2023 = len(set(re.findall(r'name="(sst\.day\.anom\.2023\.nc)"', oisst_catalog)))
    product_hits = core_product_hits(crw_page)
    crw_core_product_count = sum(1 for present in product_hits.values() if present)
    crw_core_product_ratio = crw_core_product_count / 4.0
    positive_sst_proxy_c = 1.0 if sst_anom_hits_2023 >= 1 and product_hits["hotspot"] and product_hits["dhw"] else 0.0
    dhw_proxy_c_weeks = positive_sst_proxy_c * duration_days / 7.0

    land_counter_values = {
        "land_sample_ratio": round3(land_sample_ratio),
        "gpm_peak_mean_ratio": round3(gpm_peak_mean_ratio),
        "dnbr_abs_mean": round3(dnbr_abs_mean),
        "embedding_mean": round3(embedding_mean),
        "visual_luma_delta_norm": round3(visual_luma_delta_norm),
        "population_file_share": round3(population_file_share),
    }
    land_counter_flags = {
        "land_sample_ratio_lt_0_30": land_sample_ratio < 0.30,
        "gpm_peak_mean_ratio_lt_1_50": gpm_peak_mean_ratio < 1.50,
        "dnbr_abs_mean_lt_0_10": dnbr_abs_mean < 0.10,
        "embedding_mean_lt_0_05": embedding_mean < 0.05,
        "visual_luma_delta_norm_lt_0_20": visual_luma_delta_norm < 0.20,
        "population_file_share_lt_0_50": population_file_share < 0.50,
    }
    land_counter_passes = sum(1 for passed in land_counter_flags.values() if passed)

    threshold_flags = {
        "duration_days_ge_90": duration_days >= 90,
        "sst_anom_hits_2023_ge_1": sst_anom_hits_2023 >= 1,
        "dhw_proxy_c_weeks_ge_4": dhw_proxy_c_weeks >= 4.0,
        "crw_core_product_count_eq_4": crw_core_product_count == 4,
        "crw_core_product_ratio_eq_1": crw_core_product_ratio == 1.0,
        "land_counter_passes_ge_5": land_counter_passes >= 5,
    }
    score = sum(1 for passed in threshold_flags.values() if passed)
    label = "sustained_marine_heat_stress" if score == 6 else "partial_marine_heat_stress_record"

    ledger_values = {
        "duration_days": duration_days,
        "sst_anom_hits_2023": sst_anom_hits_2023,
        "dhw_proxy_c_weeks": round3(dhw_proxy_c_weeks),
        "crw_core_product_count": crw_core_product_count,
        "crw_core_product_ratio": round3(crw_core_product_ratio),
        "land_counter_passes": land_counter_passes,
        "score": score,
    }

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "numeric",
        "target_family": "marine_heat_stress_threshold_ledger",
        "evaluation_mode": "deterministic",
        "difficulty_level": "L3",
        "requires_computation": True,
        "primary_gt": {
            "answer": label,
            "ledger_values": ledger_values,
            "land_counter_values": land_counter_values,
            "tolerances": {
                "duration_days": 0,
                "sst_anom_hits_2023": 0,
                "dhw_proxy_c_weeks": 0.002,
                "crw_core_product_ratio": 0.001,
                "land_counter_passes": 0,
                "score": 0,
                "land_ratios": 0.002,
            },
        },
        "key_values": {
            "event": {
                "event_name": event["event_name"],
                "hazard_family": event["hazard_family"],
                "hazard_label": event["hazard_label"],
                "location": anchor["spatial_window"]["location_text"],
                "span_start": dates["start_date"],
                "span_end": dates["end_date"],
            },
            "marine_product_hits": product_hits,
            "land_counter_flags": land_counter_flags,
            "threshold_flags": threshold_flags,
            "raw_context": {
                "land_sample_days": land_sample_days,
                "gpm_mean_mm": round3(gpm["stats"]["gpm_event_precip_mm_mean"]),
                "gpm_max_mm": round3(gpm["stats"]["gpm_event_precip_mm_max"]),
                "population_sum": round(float(population["population_sum"]["population"]), 3),
                "pre_luma": round3(pre_luma),
                "event_luma": round3(event_luma),
            },
        },
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "window_and_dhw_proxy",
                    "points": 4,
                    "description": "Computes the 183-day inclusive window and the 26.143 degC-week duration proxy.",
                },
                {
                    "name": "sst_anomaly_and_product_hits",
                    "points": 4,
                    "description": "Counts one 2023 daily SST anomaly catalog entry and all four Indian Ocean heat-stress product links.",
                },
                {
                    "name": "spatial_product_ratio",
                    "points": 3,
                    "description": "Computes the Indian Ocean core product ratio as 4 divided by 4, equal to 1.000.",
                },
                {
                    "name": "land_context_counterchecks",
                    "points": 4,
                    "description": "Computes the six land-context checks and gets six passes using the stated thresholds.",
                },
                {
                    "name": "score_and_label",
                    "points": 3,
                    "description": "Applies the six ledger thresholds, returns score 6, and gives the label sustained_marine_heat_stress.",
                },
                {
                    "name": "compact_json_and_scope",
                    "points": 2,
                    "description": "Returns the requested compact JSON and avoids inferring measured reef damage or exact SST anomaly magnitude.",
                },
            ],
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
        },
    }


def main() -> None:
    result = build_ground_truth()
    apply_deepened_task_frame(result)
    text = json.dumps(result, indent=2, sort_keys=True, ensure_ascii=True) + "\n"
    OUTPUT_PATH.write_text(text, encoding="utf-8")


if __name__ == "__main__":
    main()
